INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('mention_students', 'Mention students', 'Detect student entity mentions.', 'global', NULL, 140, 1, 0, '{"action_key": "mention_students", "regex_patterns": ["\\\\b(student|students|kid|kids)\\\\b"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('mention_schools', 'Mention schools', 'Detect school entity mentions.', 'global', NULL, 150, 1, 0, '{"action_key": "mention_schools", "regex_patterns": ["\\\\b(school|schools)\\\\b"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('district_terms', 'District terms', 'Detect district or LEA phrases.', 'global', NULL, 160, 1, 0, '{"action_key": "district_terms", "regex_patterns": ["\\\\b(district|school district|lea|local education agency)\\\\b"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('subgroup_terms', 'Subgroup terms', 'Detect subgroup terms.', 'global', NULL, 170, 1, 0, '{"action_key": "subgroup_terms", "regex_patterns": ["\\\\b(black|african american|african-american|hispanic|latino|el|ell|esl|lep|mll)\\\\b"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('nativity_terms', 'Nativity terms', 'Detect nativity phrases.', 'global', NULL, 180, 1, 0, '{"action_key": "nativity_terms", "substring_patterns": ["born", "birth", "birth country", "not born", "entered the us", "date entered us"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('calendar_days_off_terms', 'Calendar days off terms', 'Detect days-off phrases.', 'global', NULL, 190, 1, 0, '{"action_key": "calendar_days_off_terms", "substring_patterns": [" days off ", " day off ", " off day ", " off days ", " no school ", " school closed ", " non instructional ", " non-instructional "], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('age_extreme_terms', 'Age extreme terms', 'Detect oldest or youngest phrases.', 'global', NULL, 200, 1, 0, '{"action_key": "age_extreme_terms", "substring_patterns": [" oldest ", " youngest ", " eldest "], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('birth_month_terms', 'Birth month terms', 'Detect birth-month context phrases.', 'global', NULL, 210, 1, 0, '{"action_key": "birth_month_terms", "substring_patterns": [" birthday ", " birthdays ", " birth month ", " birthdate ", " date of birth ", " born in ", " births in "], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('name_constraint_terms', 'Name constraint terms', 'Detect name-constraint phrases.', 'global', NULL, 220, 1, 0, '{"action_key": "name_constraint_terms", "substring_patterns": ["first name", "last name", "named ", "name of "], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('explicit_preferred_name_terms', 'Explicit preferred name terms', 'Detect explicit preferred-name requests.', 'global', NULL, 230, 1, 0, '{"action_key": "explicit_preferred_name_terms", "substring_patterns": [" preferred name ", " preferred first name ", " preferred last name ", " preferred names "], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('staff_work_hint', 'Staff work hint', 'Detect staff work context phrases.', 'global', NULL, 240, 1, 0, '{"action_key": "staff_work_hint", "regex_patterns": ["\\\\b(work(s|ed|ing)?|workplace|employed|employment|teach(es|ing)?|teacher|staff|job|principal|assistant\\\\s+principal|counselor|counsellor)\\\\b"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('student_attend_hint', 'Student attend hint', 'Detect student-school context phrases.', 'global', NULL, 250, 1, 0, '{"action_key": "student_attend_hint", "regex_patterns": ["\\\\b(goes to|attend(s|ed|ing)?|enroll(ed|ment|ing)?|student)\\\\b"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('adm_hint', 'ADM hint', 'Detect ADM phrases.', 'global', NULL, 260, 1, 0, '{"action_key": "adm_hint", "regex_patterns": ["\\\\b(adm|average\\\\s+daily\\\\s+membership|base\\\\s+adm|daily\\\\s+membership|normalized\\\\s+adm)\\\\b"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('city_state_abbr', 'City state abbreviation', 'Detect city-state abbreviation patterns.', 'global', NULL, 270, 1, 0, '{"action_key": "city_state_abbr", "regex_patterns": [",\\\\s*([a-z]{2})\\\\b"], "state_codes": ["al", "ak", "az", "ar", "ca", "co", "ct", "de", "fl", "ga", "hi", "id", "il", "in", "ia", "ks", "ky", "la", "me", "md", "ma", "mi", "mn", "ms", "mo", "mt", "ne", "nv", "nh", "nj", "nm", "ny", "nc", "nd", "oh", "ok", "or", "pa", "ri", "sc", "sd", "tn", "tx", "ut", "vt", "va", "wa", "wv", "wi", "wy"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('month_names', 'Month names', 'Known month names for prompt analysis.', 'global', NULL, 280, 1, 0, '{"action_key": "month_names", "substring_patterns": ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_prompt_intent_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('time_phrases', 'Time phrases', 'Known time phrases for prompt analysis.', 'global', NULL, 290, 1, 0, '{"action_key": "time_phrases", "substring_patterns": ["this year", "last year", "current school year", "school year"], "version": 1}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_projection_policy (policy_key, name, description, scope_type, scope_workspace_id, scope_base_domain_id, priority, is_active, stop_on_match, policy_json) VALUES ('student_listing_identity_projection', 'Student listing identity projection', 'Ensure student identity concepts appear first for student listing prompts.', 'global', NULL, NULL, 100, 1, 0, '{"projection_mode": "prepend", "required_concept_keys": ["STUDENT_ID", "STUDENT_FIRST_NAME", "STUDENT_LAST_NAME"], "version": 1, "when_signals_all": ["student_listing"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), scope_base_domain_id = VALUES(scope_base_domain_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_projection_policy (policy_key, name, description, scope_type, scope_workspace_id, scope_base_domain_id, priority, is_active, stop_on_match, policy_json) VALUES ('student_listing_school_context', 'Student listing school context', 'Require school filter and school join context for student listing prompts with a school literal.', 'global', NULL, NULL, 110, 1, 0, '{"projection_mode": "prepend", "required_concept_keys": ["STUDENT_FIRST_NAME", "STUDENT_LAST_NAME"], "required_filter_concept_keys": ["SCHOOL_NAME"], "required_join_tables": ["dim_school"], "version": 1, "when_signals_all": ["student_listing", "school_literal_present"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), scope_base_domain_id = VALUES(scope_base_domain_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_projection_policy (policy_key, name, description, scope_type, scope_workspace_id, scope_base_domain_id, priority, is_active, stop_on_match, policy_json) VALUES ('human_school_filter_projection', 'Human school filter projection', 'Prefer school-name semantics over technical school identifiers for school-filter prompts unless the prompt explicitly asks for a key or code.', 'global', NULL, NULL, 120, 1, 0, '{"exclude_signals_any": ["explicit_school_key_request"], "excluded_concept_keys": ["SCHOOL_ID"], "projection_mode": "prepend", "required_concept_keys": ["SCHOOL_NAME"], "version": 1, "when_signals_all": ["needs_school_filter"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), scope_base_domain_id = VALUES(scope_base_domain_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_projection_policy (policy_key, name, description, scope_type, scope_workspace_id, scope_base_domain_id, priority, is_active, stop_on_match, policy_json) VALUES ('human_staff_role_filter_projection', 'Human staff role filter projection', 'Prefer human-readable staff role/title columns over staff classification when the prompt asks for a staff role and does not explicitly ask for classification values.', 'global', NULL, NULL, 130, 1, 0, '{"exclude_signals_any": ["explicit_staff_classification_request"], "excluded_concept_keys": ["STAFF_CLASSIFICATION"], "projection_mode": "prepend", "required_concept_keys": ["STAFF_ROLE"], "version": 1, "when_signals_all": ["staff_role_prompt"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), scope_base_domain_id = VALUES(scope_base_domain_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_projection_policy (policy_key, name, description, scope_type, scope_workspace_id, scope_base_domain_id, priority, is_active, stop_on_match, policy_json) VALUES ('school_listing_projection', 'School listing projection', 'Ensure school listing prompts lead with human-readable school identity columns.', 'global', NULL, NULL, 140, 1, 0, '{"projection_mode": "prepend", "required_column_names": ["school_name", "lea_name", "school_number"], "version": 1, "when_signals_all": ["school_listing"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), scope_base_domain_id = VALUES(scope_base_domain_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('staff_context_domain_retrieval', 'Staff context domain retrieval', 'Expand staff prompts toward assignment and workforce domains and away from unrelated student or discipline domains.', 'global', NULL, 100, 1, 0, '{"domain_name_avoid_tokens": ["student", "discipline"], "domain_name_negative_bias": 0.24, "domain_name_positive_bias": 0.18, "domain_name_prefer_tokens": ["staff", "assignment", "employee", "teacher", "workforce"], "query_specs": [{"query": "staff assignments", "source": "vector"}, {"query": "staff workplace", "source": "vector"}, {"query": "teacher employment", "source": "vector"}, {"query": "employee roster", "source": "vector"}], "version": 1, "when_signals_any": ["staff_listing", "staff_aggregate", "staff_work_context_prompt"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('student_context_domain_retrieval', 'Student context domain retrieval', 'Expand student prompts toward enrollment and demographics domains and away from unrelated discipline domains.', 'global', NULL, 110, 1, 0, '{"domain_name_avoid_tokens": ["discipline"], "domain_name_negative_bias": 0.12, "domain_name_positive_bias": 0.14, "domain_name_prefer_tokens": ["student", "demographic", "profile", "enrollment", "enrolment"], "query_specs": [{"query": "student enrollment", "source": "vector"}, {"query": "student demographics", "source": "vector"}, {"query": "student profile", "source": "vector"}], "version": 1, "when_signals_any": ["student_listing", "student_aggregate", "student_school_context_prompt"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('adm_domain_retrieval', 'ADM domain retrieval', 'Expand ADM prompts toward membership and enrollment domains and away from calendar-only domains.', 'global', NULL, 115, 1, 0, '{"domain_name_avoid_tokens": ["calendar", "term"], "domain_name_negative_bias": 0.18, "domain_name_positive_bias": 0.18, "domain_name_prefer_tokens": ["adm", "membership", "enrollment", "enrolment"], "query_specs": [{"query": "average daily membership adm base adm", "source": "vector"}, {"query": "normalized_adm report_period school_year", "source": "vector"}, {"query": "is_primary_school grade_level_adm", "source": "vector"}], "version": 1, "when_signals_all": ["adm_prompt"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('age_extreme_domain_retrieval', 'Age extreme domain retrieval', 'Bias eldest or youngest prompts toward student demographic and birth-date domains.', 'global', NULL, 120, 1, 0, '{"domain_name_avoid_tokens": ["program", "service", "membership"], "domain_name_negative_bias": 0.16, "domain_name_positive_bias": 0.18, "domain_name_prefer_tokens": ["demographic", "profile", "student"], "query_specs": [{"query": "student demographics birth date age", "source": "vector"}, {"query": "student profile date of birth", "source": "vector"}], "version": 1, "when_signals_all": ["age_extreme_prompt"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('birth_month_domain_retrieval', 'Birth month domain retrieval', 'Bias birthday and birth-month prompts toward demographic and date-of-birth domains.', 'global', NULL, 130, 1, 0, '{"domain_name_avoid_tokens": ["program", "service", "membership"], "domain_name_negative_bias": 0.18, "domain_name_positive_bias": 0.2, "domain_name_prefer_tokens": ["demographic", "profile", "student"], "query_specs": [{"query": "student demographics birth date birthday month", "source": "vector"}, {"query": "student profile date of birth month", "source": "vector"}], "version": 1, "when_signals_all": ["birth_month_prompt"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('calendar_days_off_domain_retrieval', 'Calendar days off domain retrieval', 'Bias days-off prompts toward calendar and scheduling domains with additional semantic calendar queries.', 'global', NULL, 140, 1, 0, '{"domain_name_positive_bias": 0.18, "domain_name_prefer_tokens": ["calendar", "scheduling", "schedule", "term", "semester"], "query_specs": [{"query": "academic calendar days off", "source": "vector"}, {"query": "school calendar no school non instructional days", "source": "vector"}, {"query": "calendar school day holiday schedule", "source": "vector"}, {"query": "academic calendar days off no school school day", "reasons": ["semantic_query:calendar_days_off"], "score_boost": 0.08, "source": "semantic_vector"}, {"query": "non instructional days school calendar holiday schedule", "reasons": ["semantic_query:calendar_days_off"], "score_boost": 0.06, "source": "semantic_vector"}], "version": 1, "when_signals_all": ["calendar_days_off_prompt"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('subgroup_semantic_retrieval', 'Subgroup semantic retrieval', 'Expand subgroup prompts toward race, ethnicity, and language semantics.', 'global', NULL, 150, 1, 0, '{"query_specs": [{"query": "student subgroup demographics race ethnicity language", "reasons": ["semantic_query:subgroup"], "score_boost": 0.04, "source": "semantic_vector"}], "version": 1, "when_signals_all": ["subgroup_prompt"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('semester_semantic_retrieval', 'Semester semantic retrieval', 'Expand semantic retrieval when concept grounding points at semester or term concepts.', 'global', NULL, 160, 1, 0, '{"query_specs": [{"query": "academic calendar semester terms", "reasons": ["semantic_query:semester"], "score_boost": 0.05, "source": "semantic_vector"}], "version": 1, "when_concept_key_patterns_any": ["SEMESTER", "TERM"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('school_year_semantic_retrieval', 'School year semantic retrieval', 'Expand semantic retrieval when concept grounding points at school-year concepts.', 'global', NULL, 170, 1, 0, '{"query_specs": [{"query": "school year academic calendar enrollment", "reasons": ["semantic_query:school_year"], "score_boost": 0.04, "source": "semantic_vector"}], "version": 1, "when_concept_key_patterns_any": ["SCHOOL_YEAR", "_YEAR"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
INSERT INTO planner_retrieval_policy (policy_key, name, description, scope_type, scope_workspace_id, priority, is_active, stop_on_match, policy_json) VALUES ('nativity_semantic_retrieval', 'Nativity semantic retrieval', 'Expand semantic retrieval when grounding points at country-of-birth style concepts.', 'global', NULL, 180, 1, 0, '{"query_specs": [{"query": "student demographics birth country nativity", "reasons": ["semantic_query:nativity"], "score_boost": 0.06, "source": "semantic_vector"}, {"query": "country of birth student profile demographics", "reasons": ["semantic_query:nativity"], "score_boost": 0.04, "source": "semantic_vector"}], "version": 1, "when_concept_key_patterns_any": ["COUNTRY"]}') ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), scope_type = VALUES(scope_type), scope_workspace_id = VALUES(scope_workspace_id), priority = VALUES(priority), is_active = VALUES(is_active), stop_on_match = VALUES(stop_on_match), policy_json = VALUES(policy_json), updated_at = CURRENT_TIMESTAMP;
